blocks.code:
/* Иконка перед ссылкой */
.external-link::before {
  content: "🔗 ";
}

/* Декоративная линия после заголовка */
h2::after {
  content: "";
  display: block;
  width: 60px;
  height: 3px;
  background: skyblue;
  margin-top: 8px;
}

/* Текст */
.quote::before { content: "«"; }
.quote::after  { content: "»"; }

/* Пустое (для декоративных линий) */
h2::after { content: ""; }

/* Атрибут HTML */
.link::after { content: attr(href); }

/* Счётчик */
ol { counter-reset: item; }
li::before {
  counter-increment: item;
  content: counter(item) ". ";
  font-weight: bold;
}

p::first-letter {
  font-size: 2em;
  font-weight: bold;
  color: navy;
  float: left;
  margin-right: 8px;
}

li::marker {
  color: skyblue;
  font-size: 1.2em;
}

/* Кастомный маркер */
ul.checklist li::marker {
  content: "✅ ";
}
